import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Глава 106 | Уточнение ступеней · Чувственно-Истоковая Ступень · Сравнение хищнического и симбиотического лагерей","description":"","frontmatter":{"title":"Глава 106 | Уточнение ступеней · Чувственно-Истоковая Ступень · Сравнение хищнического и симбиотического лагерей","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","路线对比"],"related":["04-掠夺式修炼体系批判","01-衡元宙核心世界观","14-修炼境界统一划分"]},"headers":[],"relativePath":"ru/106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"ru/106_模块1-感元境-掠夺派vs共生派对比.md"}'),i={name:"ru/106_模块1-感元境-掠夺派vs共生派对比.md"};function l(o,t,h,n,s,_){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="глава-106-чувственно-истоковая-ступень-системное-сравнение-хищнического-и-симбиотического-лагереи" tabindex="-1">Глава 106 | Чувственно-Истоковая Ступень: системное сравнение хищнического и симбиотического лагерей <a class="header-anchor" href="#глава-106-чувственно-истоковая-ступень-системное-сравнение-хищнического-и-симбиотического-лагереи" aria-label="Permalink to &quot;Глава 106 | Чувственно-Истоковая Ступень: системное сравнение хищнического и симбиотического лагерей&quot;">​</a></h1><blockquote><p>Модуль: Модуль первый · Глубокое уточнение ступеней | Опорные документы: 04, 01, 14</p></blockquote><h2 id="введение-две-логики-культивации-два-вида-вселеннои" tabindex="-1">Введение: две логики культивации, два вида вселенной <a class="header-anchor" href="#введение-две-логики-культивации-два-вида-вселеннои" aria-label="Permalink to &quot;Введение: две логики культивации, два вида вселенной&quot;">​</a></h2><p>Чувственно-Истоковая Ступень — не только старт культивации, но и самый первый перекрёсток мировоззрения: с самого первого поглощения энергии культиватор уже стоит на развилке — либо «я беру у мира», либо «я расту вместе с миром». Эти две фразы звучат близко, но ведут в две совершенно разные вселенные: одна — охотничьи угодья, где сильный ест слабого; другая — жизненное сообщество, где все существа восходят вместе.</p><p>Эта статья даёт системное сравнение Хищнической Системы Культивации и Симбиотической Цивилизации Якоря.</p><p>Шесть Высших Аксиом — сама разделительная черта: Аксиома Антихищничества отделяет «брать» от «расти»; Аксиома Республики Десяти Тысяч Рас отделяет «только моя раса» от «все расы»; Аксиома Коллективного Измерения отделяет «я восхожу один» от «мы восходим вместе»; Аксиома Причинной Самодисциплины отделяет «долг в другом месте» от «я несу свой собственный плод»; Аксиома Приоритета Закона отделяет «правила мне на удобство» от «закон стабилен и самосогласован». Закон Всеобщей Бесконечной Равноправности Всех Существ устанавливает, что каждое существо изначально несёт Основную Бесконечную Силу: бездельники сохраняют гарантированную нижнюю бесконечность и не будут уничтожены временем, а трудяги и юные высочайшие могут наслаивать высшие уровни бесконечности. Изначальная бесконечность присуща всем — хищническая логика «выжить могут только сильные» уже недействительна с виду.</p><h2 id="i-сводная-таблица-системного-сравнения" tabindex="-1">I. Сводная таблица системного сравнения <a class="header-anchor" href="#i-сводная-таблица-системного-сравнения" aria-label="Permalink to &quot;I. Сводная таблица системного сравнения&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Измерение</th><th>Хищнический лагерь</th><th>Симбиотический лагерь (Якорь)</th></tr></thead><tbody><tr><td>Источник энергии</td><td>Пожирает чужой исток</td><td>Берёт из мирового кругооборота, возвращает</td></tr><tr><td>Отношение к слабым</td><td>Естественный отбор, слабый — умри</td><td>Ограждение для всех, ни одного не забыть</td></tr><tr><td>Логика потолка</td><td>Один вершок над кладбищем</td><td>Целое восходит вместе</td></tr><tr><td>Временной горизонт</td><td>Слить сейчас, выбросить потом</td><td>Двусторонний кругооборот, устойчиво</td></tr><tr><td>Отношение к риску</td><td>Риск есть фильтр</td><td>Риск есть проблема на управление</td></tr><tr><td>Этическая основа</td><td>Сила делает право</td><td>Причинная самодисциплина</td></tr><tr><td>Конечная цель</td><td>Властелин одного звёздного сектора</td><td>Гиперплюралистическая Ступень Уравновешенного Якоря</td></tr></tbody></table><h2 id="ii-три-заблуждения-хищнического-лагеря" tabindex="-1">II. Три заблуждения хищнического лагеря <a class="header-anchor" href="#ii-три-заблуждения-хищнического-лагеря" aria-label="Permalink to &quot;II. Три заблуждения хищнического лагеря&quot;">​</a></h2><ol><li>Заблуждение с нулевой суммой: он верит, что сила постоянна, значит, чтобы её взять, надо отнять у другого — слеп к тому, что энергия мирового кругооборота возобновляема и расширяема.</li><li>Заблуждение естественного отбора: он верит, что слабые заслуживают отбора — слеп к тому, что нижняя бесконечность бездельников позволяет медленным идти вровень, не будучи раздавленными.</li><li>Заблуждение «просвещённого хищника»: он верит, что добрый хищник есть лучший хищник — слеп к тому, что сама структура хищничества и есть болезнь, не нрав хищника.</li></ol><h2 id="iii-«просвещенныи-хищник»-и-историческая-регрессия" tabindex="-1">III. «Просвещённый хищник» и историческая регрессия <a class="header-anchor" href="#iii-«просвещенныи-хищник»-и-историческая-регрессия" aria-label="Permalink to &quot;III. «Просвещённый хищник» и историческая регрессия&quot;">​</a></h2><p>Так называемый просвещённый хищник — то есть сильный, который не убивает без удали, который «делится малым» со слабыми, который зовёт себя благотворительным, — есть опаснейший самообман хищнического лагеря. Добрый охотник всё ещё охотник; его доброта лишь утончённое управление дичью. История не раз показывает, что «просвещённая» эра хищнической системы всегда накануне регресса: раз охотничьи угодья истощены, «благотворительные» сильные первые же обращаются против своих.</p><h2 id="iv-праведныи-плут-предупреждение-«избранным»" tabindex="-1">IV. Праведный плут: предупреждение «избранным» <a class="header-anchor" href="#iv-праведныи-плут-предупреждение-«избранным»" aria-label="Permalink to &quot;IV. Праведный плут: предупреждение «избранным»&quot;">​</a></h2><p>Симбиотический лагерь не притворяется, что его собственный лагерь идеален. Самая коварная разновидность — «праведный плут»: тот, кто облачается в мантию правосудия, чтобы всё ещё грабить, кто говорит «я делаю это ради симбиоза», сливая других ради собственного прорыва.</p><p>Возьмём Лин Хао, героя этой вселенной, как пробный камень: его путь — не стать сильнейшим на охотничьих угодьях, но доказать, что сильный может восходить, оставляя слабым путь домой. Каждый раз, когда его искушает мысль «я особенный, потому правила ко мне неписаны», — это ровно тот миг, когда стучится Внутренний Бес Удобного Пути; эту внутреннюю черту обязан держать каждый культиватор симбиотического лагеря.</p><h2 id="v-пять-ключевых-точек-опоры" tabindex="-1">V. Пять ключевых точек опоры <a class="header-anchor" href="#v-пять-ключевых-точек-опоры" aria-label="Permalink to &quot;V. Пять ключевых точек опоры&quot;">​</a></h2><ul><li>Анти-потеря энергоуровня: «сильный ест слабого» хищнического лагеря расточает больше эволюционного потенциала, чем любая война; двусторонний кругооборот симбиотического лагеря и есть истинная высокая эффективность.</li><li>Анти-хищничество: каждая строка сводной таблицы — красная черта, которую симбиотический лагерь не переступит.</li><li>Сравнение с потолком Тан Луо: потолок хищнического лагеря — властелин над кладбищем; потолок симбиотического лагеря поднимает весь космос.</li><li>Полное покрытие Десяти Тысяч Рас: сводная таблица охватывает всякое измерение — от источника энергии до конечной цели, без слепых углов.</li><li>Гиперплюралистическая полная открытость: само сравнение есть открытая улика — хищнический лагерь не смеет его опубликовать, ибо каждое измерение разоблачает его собственную мелкость.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Таблице не нужна риторика; две колонки уже говорят. В Чувственно-Истоковой Ступени первое поглощение, которое выбирает культиватор, решает, в какой колонке он будет стоять всю остальную жизнь — потому это сравнение помещено в самое начало всей библиотеки: дабы каждый читатель до выбора пути увидел, в какую вселенную он собирается войти.</p><h2 id="ссылки" tabindex="-1">Ссылки <a class="header-anchor" href="#ссылки" aria-label="Permalink to &quot;Ссылки&quot;">​</a></h2><ul><li>Связанные документы: <a href="./04-掠夺式修炼体系批判.html">04-Критика Хищнической Системы Культивации</a> · <a href="./01-衡元宙核心世界观.html">01-Ядро мировоззрения Хэн Юаньчжоу</a> · <a href="./14-修炼境界统一划分.html">14-Единая классификация ступеней культивации</a></li><li>Официальный сайт: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',21)])])}const p=a(i,[["render",l]]);export{c as __pageData,p as default};
